func (c *BankCipher) Rewrap(sealed, aad []byte) ([]byte, error) {
	_, err := c.Cipher.Open(sealed, aad)
	id, _, _ := splitSealedField(sealed)
	if err == nil && id == c.activeID {
		return sealed, nil
	}
	plain, err := c.Open(sealed, aad)
	if err != nil {
		return nil, ErrOpen
	}
	return c.Seal(plain, aad)
}
